package com.worksphere.service; import com.worksphere.entity.*; import com.worksphere.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class StrikeService {private final StrikeRepository repo;private final WorkerProfileRepository profiles;public StrikeService(StrikeRepository r,WorkerProfileRepository p){repo=r;profiles=p;} public Strike add(User u,String reason){Strike s=new Strike();s.user=u;s.reason=reason;s.status=StrikeStatus.ACTIVE;s=repo.save(s);profiles.findByUserId(u.id).ifPresent(p->{p.strikeCount=repo.findByUserIdAndStatus(u.id,StrikeStatus.ACTIVE).size();profiles.save(p);});return s;} public List<Strike> all(){return repo.findAllByOrderByCreatedAtDesc();}}
